using System;
using System.IO;
using System.Linq;
using System.Text;
using System.Collections.Generic;
using System.Runtime.InteropServices;
using System.Security.Principal;
using System.Diagnostics;
using System.Web.Script.Serialization;
using Microsoft.Win32;
namespace MonitorSlice {
static class DriverSetup {
 const string Key="SOFTWARE\\MikeTheTech\\VirtualDisplayDriver";
 static readonly Guid DisplayClass=new Guid("4D36E968-E325-11CE-BFC1-08002BE10318");
 static readonly string Home=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.CommonApplicationData),"MonitorSlice");
 static readonly string StateFile=Path.Combine(Home,"setup-state.json"),Config=Path.Combine(Home,"Driver","vdd_settings.xml");
 [StructLayout(LayoutKind.Sequential)]struct Info{public int Size;public Guid Class;public uint Instance;public IntPtr Reserved;}
 [DllImport("setupapi.dll",CharSet=CharSet.Unicode,SetLastError=true)]static extern IntPtr SetupDiGetClassDevs(ref Guid guid,string enumerator,IntPtr parent,uint flags);
 [DllImport("setupapi.dll",SetLastError=true)]static extern bool SetupDiEnumDeviceInfo(IntPtr list,uint index,ref Info info);
 [DllImport("setupapi.dll",CharSet=CharSet.Unicode,SetLastError=true)]static extern bool SetupDiGetDeviceRegistryProperty(IntPtr list,ref Info info,uint property,out uint type,byte[] bytes,int length,out uint required);
 [DllImport("setupapi.dll",CharSet=CharSet.Unicode,SetLastError=true)]static extern bool SetupDiGetDeviceInstanceId(IntPtr list,ref Info info,StringBuilder id,int size,out int required);
 [DllImport("setupapi.dll",SetLastError=true)]static extern IntPtr SetupDiCreateDeviceInfoList(ref Guid guid,IntPtr parent);
 [DllImport("setupapi.dll",CharSet=CharSet.Unicode,SetLastError=true)]static extern bool SetupDiCreateDeviceInfo(IntPtr list,string name,ref Guid guid,string description,IntPtr parent,uint flags,ref Info info);
 [DllImport("setupapi.dll",CharSet=CharSet.Unicode,SetLastError=true)]static extern bool SetupDiSetDeviceRegistryProperty(IntPtr list,ref Info info,uint property,byte[] bytes,int length);
 [DllImport("setupapi.dll",SetLastError=true)]static extern bool SetupDiCallClassInstaller(uint function,IntPtr list,ref Info info);
 [DllImport("setupapi.dll",SetLastError=true)]static extern bool SetupDiRemoveDevice(IntPtr list,ref Info info);
 [DllImport("setupapi.dll")]static extern bool SetupDiDestroyDeviceInfoList(IntPtr list);
 [DllImport("newdev.dll",CharSet=CharSet.Unicode,SetLastError=true)]static extern bool UpdateDriverForPlugAndPlayDevices(IntPtr parent,string id,string inf,uint flags,out bool reboot);
 public class State {public int Version=1;public string Phase="ready",OriginalPath,OriginalXml,BackupXml,BackupPath;public bool Reboot;public List<string> Devices=new List<string>(),Added=new List<string>();}
 static void Check(bool ok){if(!ok)throw new System.ComponentModel.Win32Exception(Marshal.GetLastWin32Error());}
 static string Id(IntPtr list,ref Info info){var b=new StringBuilder(512);int n;Check(SetupDiGetDeviceInstanceId(list,ref info,b,b.Capacity,out n));return b.ToString();}
 static List<string> Devices(){var result=new List<string>();Guid g=DisplayClass;IntPtr list=SetupDiGetClassDevs(ref g,null,IntPtr.Zero,0);if(list==new IntPtr(-1))throw new System.ComponentModel.Win32Exception();try{for(uint i=0;;i++){var d=new Info{Size=Marshal.SizeOf(typeof(Info))};if(!SetupDiEnumDeviceInfo(list,i,ref d)){if(Marshal.GetLastWin32Error()==259)break;Check(false);}uint type,n;var b=new byte[4096];if(SetupDiGetDeviceRegistryProperty(list,ref d,1,out type,b,b.Length,out n)&&Encoding.Unicode.GetString(b,0,(int)n).Split('\0').Any(x=>x.Equals("Root\\MttVDD",StringComparison.OrdinalIgnoreCase)))result.Add(Id(list,ref d));}}finally{SetupDiDestroyDeviceInfoList(list);}return result;}
 static string RegistryPath(){using(var k=Registry.LocalMachine.OpenSubKey(Key))return k==null?null:k.GetValue("VDDPATH") as string;}
 static void SetPath(string path){using(var k=Registry.LocalMachine.CreateSubKey(Key)){if(path==null)k.DeleteValue("VDDPATH",false);else k.SetValue("VDDPATH",path);}}
 static State Read(){return File.Exists(StateFile)?new JavaScriptSerializer().Deserialize<State>(File.ReadAllText(StateFile)):null;}
 static void Save(State state){Directory.CreateDirectory(Home);File.WriteAllText(StateFile+".tmp",new JavaScriptSerializer().Serialize(state));if(File.Exists(StateFile))File.Replace(StateFile+".tmp",StateFile,StateFile+".bak");else File.Move(StateFile+".tmp",StateFile);}
 static void Remove(IEnumerable<string> ids){var targets=new HashSet<string>(ids,StringComparer.OrdinalIgnoreCase);var allowed=new HashSet<string>(Devices(),StringComparer.OrdinalIgnoreCase);Guid g=DisplayClass;IntPtr list=SetupDiGetClassDevs(ref g,null,IntPtr.Zero,0);if(list==new IntPtr(-1))throw new System.ComponentModel.Win32Exception();try{var found=new List<Info>();for(uint i=0;;i++){var d=new Info{Size=Marshal.SizeOf(typeof(Info))};if(!SetupDiEnumDeviceInfo(list,i,ref d))break;string id=Id(list,ref d);if(targets.Contains(id)&&allowed.Contains(id))found.Add(d);}foreach(var value in found){var d=value;Check(SetupDiRemoveDevice(list,ref d));}}finally{SetupDiDestroyDeviceInfoList(list);}}
 static void Restart(IEnumerable<string> ids){foreach(string id in ids){if(!System.Text.RegularExpressions.Regex.IsMatch(id,@"^ROOT\\DISPLAY\\[0-9A-F]+$",System.Text.RegularExpressions.RegexOptions.IgnoreCase))throw new Exception("장치 식별자 확인 실패");using(var p=Process.Start(new ProcessStartInfo("pnputil.exe","/restart-device "+id){UseShellExecute=false,CreateNoWindow=true})){p.WaitForExit();if(p.ExitCode!=0)throw new Exception("장치 재시작 실패. Windows를 다시 시작한 뒤 복구를 눌러 주세요.");}}}
 static State Adopt(){var ids=Devices();string folder=Path.GetDirectoryName(Config);string path=RegistryPath();if(ids.Count==0){if(path!=null)throw new Exception("다른 가상 디스플레이 설정이 있어 보존했습니다. 기존 드라이버를 먼저 정리해 주세요.");return new State{OriginalPath=path,OriginalXml=File.Exists(Config)?File.ReadAllText(Config):null};}string legacy=Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"data","isolated-driver.json");if(File.Exists(legacy)&&string.Equals(path,folder,StringComparison.OrdinalIgnoreCase)){var added=new JavaScriptSerializer().Deserialize<List<string>>(File.ReadAllText(legacy));if(ids.Count==4&&added.Count==3&&added.All(x=>ids.Contains(x)))return new State{Devices=ids};}throw new Exception("다른 프로그램의 가상 디스플레이를 발견했습니다. 기존 장치는 변경하지 않았습니다.");}
 static void RestoreXml(string xml){Directory.CreateDirectory(Path.GetDirectoryName(Config));if(xml==null){if(File.Exists(Config))File.Delete(Config);}else File.WriteAllText(Config,xml);}
 static void Recover(State s){if(s.Phase=="ready")return;bool changed=(File.Exists(Config)?File.ReadAllText(Config):null)!=s.BackupXml||RegistryPath()!=s.BackupPath;Remove(s.Added);s.Devices=s.Devices.Except(s.Added,StringComparer.OrdinalIgnoreCase).ToList();RestoreXml(s.BackupXml);SetPath(s.BackupPath);if(changed)Restart(s.Devices.Intersect(Devices(),StringComparer.OrdinalIgnoreCase));s.Added.Clear();s.Phase="ready";Save(s);}
 public static string ConfigXml(){var virtualNames=new HashSet<string>(Displays.Virtual().Select(x=>x.Name));var sizes=System.Windows.Forms.Screen.AllScreens.Where(x=>!virtualNames.Contains(x.DeviceName)).SelectMany(x=>new[]{x.Bounds,new System.Drawing.Rectangle(0,0,x.Bounds.Height,x.Bounds.Width)}).SelectMany(b=>Layouts.Keys.SelectMany(k=>Layouts.Create(k).Select(r=>Layouts.Bounds(r,b,0).Size))).Distinct().ToArray();if(sizes.Length==0)throw new Exception("실제 모니터가 없습니다.");var physical=Displays.All().Where(x=>x.Attached&&!virtualNames.Contains(x.Name)).OrderByDescending(x=>x.Primary).FirstOrDefault();string gpu=physical==null?"default":System.Security.SecurityElement.Escape(physical.Description??"default");return "<?xml version=\"1.0\"?><vdd_settings><monitors><count>1</count></monitors><gpu><friendlyname>"+gpu+"</friendlyname></gpu><global><g_refresh_rate>60</g_refresh_rate></global><resolutions>"+string.Join("",sizes.Select(x=>"<resolution><width>"+x.Width+"</width><height>"+x.Height+"</height><refresh_rate>60</refresh_rate></resolution>"))+"</resolutions><logging><logging>false</logging><debuglogging>false</debuglogging></logging></vdd_settings>";}
 static void MigrateLegacy(){if(File.Exists(StateFile))return;string legacy=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.CommonApplicationData),"Monitor"+"Split");string oldState=Path.Combine(legacy,"setup-state.json"),oldConfig=Path.Combine(legacy,"Driver","vdd_settings.xml");if(!File.Exists(oldState)||!string.Equals(RegistryPath(),Path.GetDirectoryName(oldConfig),StringComparison.OrdinalIgnoreCase))return;var state=new JavaScriptSerializer().Deserialize<State>(File.ReadAllText(oldState));if(state.Phase!="ready"||state.Devices.Count!=4||Devices().Except(state.Devices,StringComparer.OrdinalIgnoreCase).Any())throw new Exception("이전 설치의 복구를 완료한 뒤 새 버전을 실행해 주세요.");try{RestoreXml(File.ReadAllText(oldConfig));Save(state);SetPath(Path.GetDirectoryName(Config));}catch{SetPath(Path.GetDirectoryName(oldConfig));if(File.Exists(StateFile))File.Delete(StateFile);throw;}}
 public static void Run(string operation){if(!new WindowsPrincipal(WindowsIdentity.GetCurrent()).IsInRole(WindowsBuiltInRole.Administrator))throw new Exception("Windows 관리자 승인이 필요합니다.");MigrateLegacy();State s=Read();string currentPath=RegistryPath();if(s!=null&&currentPath!=null&&!string.Equals(currentPath,Path.GetDirectoryName(Config),StringComparison.OrdinalIgnoreCase))throw new Exception("다른 프로그램의 드라이버 설정 경로가 변경되어 기존 설정을 보존했습니다.");if(operation=="recover"){if(s!=null){if(s.Phase!="ready")Recover(s);else{Restart(s.Devices.Intersect(Devices(),StringComparer.OrdinalIgnoreCase));Run("install");}}return;}if(s==null)s=Adopt();if(s.Phase!="ready")Recover(s);
 if(operation=="remove"){Remove(s.Devices);RestoreXml(s.OriginalXml);SetPath(s.OriginalPath);if(File.Exists(StateFile))File.Delete(StateFile);return;}
 string inf=Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"driver","package","VirtualDisplayDriver","MttVDD.inf");foreach(var name in new[]{"MttVDD.inf","MttVDD.dll","mttvdd.cat"})if(!File.Exists(Path.Combine(Path.GetDirectoryName(inf),name)))throw new Exception("배포 파일이 누락됐습니다. ZIP 전체를 압축 해제해 주세요.");
 var foreign=Devices().Except(s.Devices,StringComparer.OrdinalIgnoreCase).ToArray();if(foreign.Length!=0)throw new Exception("다른 프로그램의 가상 디스플레이가 있어 변경을 중단했습니다.");if(operation!="test-failure"&&s.Devices.Count==4&&Devices().Count==4&&s.Devices.All(x=>Devices().Contains(x))&&File.Exists(Config)&&File.ReadAllText(Config)==ConfigXml()){Save(s);return;}s.BackupXml=File.Exists(Config)?File.ReadAllText(Config):null;s.BackupPath=RegistryPath();s.Added.Clear();s.Phase="installing";Save(s);
 try{RestoreXml(ConfigXml());SetPath(Path.GetDirectoryName(Config));if(operation=="test-failure")throw new Exception("자동 복구 검사 실패 주입");s.Devices=s.Devices.Intersect(Devices(),StringComparer.OrdinalIgnoreCase).ToList();Guid g=DisplayClass;IntPtr list=SetupDiCreateDeviceInfoList(ref g,IntPtr.Zero);if(list==new IntPtr(-1))throw new System.ComponentModel.Win32Exception();try{while(s.Devices.Count<4){var d=new Info{Size=Marshal.SizeOf(typeof(Info))};Check(SetupDiCreateDeviceInfo(list,"Display",ref g,"Monitor Slice Virtual Display",IntPtr.Zero,1,ref d));var hw=Encoding.Unicode.GetBytes("Root\\MttVDD\0\0");Check(SetupDiSetDeviceRegistryProperty(list,ref d,1,hw,hw.Length));string id=Id(list,ref d);s.Added.Add(id);s.Devices.Add(id);Save(s);Check(SetupDiCallClassInstaller(0x19,list,ref d));}bool reboot=false;if(s.Added.Count>0||Displays.Virtual().Count<4)Check(UpdateDriverForPlugAndPlayDevices(IntPtr.Zero,"Root\\MttVDD",inf,5,out reboot));s.Reboot=reboot;}finally{SetupDiDestroyDeviceInfoList(list);}Restart(s.Devices.Except(s.Added,StringComparer.OrdinalIgnoreCase));for(int attempt=0;attempt<100&&!s.Reboot&&Displays.Virtual().Count<4;attempt++)System.Threading.Thread.Sleep(100);if(Devices().Count!=4)throw new Exception("독립 장치 네 개를 확인하지 못했습니다.");s.Phase="ready";s.Added.Clear();Save(s);}catch{Recover(s);throw;}}
 }
}
